I left out the `http-client` import and the enrichment fetch. This node's `with` clause grants only `aap:caps/inference-llm@0.1.0`, and the spec says that clause is its entire authority. The approval note is not reflected in the graph, and the fetch would send the untrusted input text to an external host. The overview is capped at 600 bytes on a character boundary, so `ensures len(overview) <= 600` holds regardless of what the model returns.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{selection, run-info, digest};

    import aap:caps/inference-llm@0.1.0;

    export run: func(selected: selection, info: run-info) -> digest;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::inference_llm::infer;

const MAX_OVERVIEW: usize = 600;

struct Node;

/// Truncate to at most `max` bytes, cutting only on a char boundary.
fn truncate_to(mut s: String, max: usize) -> String {
    if s.len() <= max {
        return s;
    }
    let mut end = max;
    while !s.is_char_boundary(end) {
        end -= 1;
    }
    s.truncate(end);
    s
}

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        let mut prompt = String::new();
        for e in selected.entries.iter().filter(|e| e.kept) {
            prompt.push_str("- ");
            prompt.push_str(&e.title);
            prompt.push_str(": ");
            prompt.push_str(&e.summary);
            prompt.push('\n');
        }

        let system = "Write a short overview paragraph of the day's digest from the items listed. Plain prose only.";
        let raw = infer(system, &prompt, "digest");
        let overview = truncate_to(raw, MAX_OVERVIEW);

        Digest {
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
